// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool ok;
        vm.prank(caller);
        try c.paused() returns (bool val) {
            ok = val == false;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
